#!/bin/sh
# Package a shader-slang release into crates no larger than the crates.io limit.
#
# The packaged release is hard-coded. See the "tag" variable below.
#
# Set SHADER_SLANG_SOURCE_CHECKOUT to reuse a checkout instead of cloning.
# All crate versions come from workspace.package in the root Cargo.toml.
# Generated files are placed in shader-slang-src-*; shader-slang-src itself
# ties the partitions together.

set -eu

if [ "$#" -gt 0 ]; then
    echo "usage: $0" >&2
    exit 2
fi

tag=v2026.22
release=${tag#v}

script_dir=$(CDPATH='' cd "$(dirname "$0")" && pwd)
root=$(CDPATH='' cd "$script_dir/.." && pwd)
version=$(awk '
    /^\[workspace\.package\]$/ { in_package = 1; next }
    /^\[/ { in_package = 0 }
    in_package && $1 == "version" {
        gsub(/["[:space:]]/, "", $3)
        print $3
        exit
    }
' "$root/Cargo.toml")
case "$version" in
    [0-9]*.[0-9]*.[0-9]*) ;;
    *)
        echo "could not read workspace.package.version from $root/Cargo.toml" >&2
        exit 1
        ;;
esac

work_dir="$root/target/source-packaging/$tag"
source_dir=${SHADER_SLANG_SOURCE_CHECKOUT:-$work_dir/checkout}
mkdir -p "$work_dir"
if [ -z "${SHADER_SLANG_SOURCE_CHECKOUT:-}" ]; then
    rm -rf "$source_dir"
    git -c core.longpaths=true clone \
        --depth 1 \
        --branch "$tag" \
        --recurse-submodules \
        --shallow-submodules \
        https://github.com/shader-slang/slang.git \
        "$source_dir"
fi
if [ ! -f "$source_dir/CMakeLists.txt" ]; then
    echo "shader-slang checkout is incomplete: $source_dir" >&2
    exit 1
fi
find "$source_dir" -name .git -prune -exec rm -rf {} +

# Only generated partition crates are removed. The aggregator is regenerated
# below; shader-slang-dev is left untouched (its dependency on
# shader-slang-src uses the caret requirement ^1).
find "$root" -mindepth 1 -maxdepth 1 -type d -name 'shader-slang-src-*' \
    -exec rm -rf {} +
mkdir -p "$root/shader-slang-src/src"

components="$work_dir/components"
items="$work_dir/items"
items_dir="$work_dir/item-archives"
bins_dir="$work_dir/bins"
partition_limit=9437184
: > "$components"
: > "$items"
rm -rf "$items_dir" "$bins_dir"
mkdir -p "$items_dir" "$bins_dir"

cat > "$root/shader-slang-src/Cargo.toml" <<EOF
[package]
name = "shader-slang-src"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
keywords.workspace = true
categories.workspace = true
description = "Vendored shader-slang source and build artifacts"
build = "build.rs"
readme = "README.md"

[build-dependencies]
cmake = "0.1"
tar = "0.4"
EOF

cat > "$root/shader-slang-src/src/sources.rs" <<'EOF'
// Generated by devops/package-shader-slang-source.sh.
pub const SOURCE_ARCHIVES: &[&str] = &[
EOF

cat > "$root/shader-slang-src/src/slang_version.rs" <<EOF
// Generated by devops/package-shader-slang-source.sh.
pub const SLANG_VERSION: &str = "$release";
EOF

crate_suffix() {
    suffix=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | tr -cs 'a-z0-9' '-')
    while [ "${suffix#-}" != "$suffix" ]; do suffix=${suffix#-}; done
    while [ "${suffix%-}" != "$suffix" ]; do suffix=${suffix%-}; done
    if [ -z "$suffix" ]; then suffix=source; fi
    if [ "${#suffix}" -gt 46 ]; then
        hash=$(printf '%s' "$2" | cksum)
        hash=${hash%% *}
        suffix=$(printf '%s' "$suffix" | cut -c 1-36)
        while [ "${suffix%-}" != "$suffix" ]; do suffix=${suffix%-}; done
        suffix="$suffix-$hash"
    fi
    printf '%s\n' "$suffix"
}

write_partition() {
    suffix=$1
    shift
    crate_name="shader-slang-src-$suffix"
    crate_dir="$root/$crate_name"
    rust_name=$(printf '%s' "$crate_name" | tr '-' '_')

    mkdir -p "$crate_dir/src"
    tar -cf "$crate_dir/source.tar" -C "$source_dir" "$@"

    cat > "$crate_dir/Cargo.toml" <<EOF
[package]
name = "$crate_name"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
description = "Shader Slang source partition $suffix"
include = ["source.tar", "src/lib.rs"]
EOF
    cat > "$crate_dir/src/lib.rs" <<'EOF'
//! Source archive consumed by the `shader-slang-src` build script.

/// Absolute path to this crate's shader-slang source archive.
pub const SOURCE_ARCHIVE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/source.tar");
EOF

    printf '%s\n' "$crate_name" >> "$components"
    printf '    %s::SOURCE_ARCHIVE,\n' "$rust_name" >> "$root/shader-slang-src/src/sources.rs"
}

# Measure a group of root files as one packable item.
emit_paths() {
    category=$1
    suffix=$(crate_suffix "$2" "$2")
    item_base="$items_dir/$category-$suffix"
    shift 2
    tar -cf "$item_base.tar" -C "$source_dir" "$@"
    item_size=$(gzip -c "$item_base.tar" | wc -c)
    item_size=$(printf '%s' "$item_size" | tr -d '[:space:]')
    if [ "$item_size" -gt "$partition_limit" ]; then
        echo "source file group exceeds the partition threshold: $suffix" >&2
        exit 1
    fi
    : > "$item_base.paths"
    for relative do
        printf '%s\n' "$relative" >> "$item_base.paths"
    done
    printf '%s\t%s\t%s\n' "$item_size" "$category" "$suffix" >> "$items"
}

# Measure one source directory, recursively splitting it only when its
# compressed size exceeds the 9 MiB packing limit.
emit_item() {
    suffix=$(crate_suffix "$2" "$3")
    item_base="$items_dir/$1-$suffix"
    tar -cf "$item_base.tar" -C "$source_dir" "$3"
    item_size=$(gzip -c "$item_base.tar" | wc -c)
    item_size=$(printf '%s' "$item_size" | tr -d '[:space:]')
    if [ "$item_size" -le "$partition_limit" ]; then
        printf '%s\n' "$3" > "$item_base.paths"
        printf '%s\t%s\t%s\n' "$item_size" "$1" "$suffix" >> "$items"
        return
    fi
    rm -f "$item_base.tar"
    if [ ! -d "$source_dir/$3" ]; then
        echo "one source file exceeds the partition threshold: $3" >&2
        exit 1
    fi
    for child in "$source_dir/$3"/* "$source_dir/$3"/.[!.]* "$source_dir/$3"/..?*; do
        if [ ! -e "$child" ] && [ ! -L "$child" ]; then continue; fi
        emit_item "$1" "$2-${child##*/}" "$3/${child##*/}"
    done
}

# Root files form one item; top-level directories retain their identity until
# the bin-packing pass. Core and external items are packed independently.
set --
for path in "$source_dir"/* "$source_dir"/.[!.]* "$source_dir"/..?*; do
    if [ -f "$path" ] || [ -L "$path" ]; then
        set -- "$@" "${path##*/}"
    fi
done
emit_paths core root-files "$@"

for path in "$source_dir"/* "$source_dir"/.[!.]* "$source_dir"/..?*; do
    if [ ! -d "$path" ]; then continue; fi
    name=${path##*/}
    if [ "$name" = external ]; then
        set --
        for child in "$path"/* "$path"/.[!.]* "$path"/..?*; do
            if [ -f "$child" ] || [ -L "$child" ]; then
                set -- "$@" "external/${child##*/}"
            fi
        done
        emit_paths external root-files "$@"
        for child in "$path"/* "$path"/.[!.]* "$path"/..?*; do
            if [ -d "$child" ]; then
                emit_item external "${child##*/}" "external/${child##*/}"
            fi
        done
    else
        emit_item core "$name" "$name"
    fi
done

# Best-fit decreasing: place each large item in the fullest compatible bin
# that stays under 9 MiB. This leaves 1 MiB for packaging overhead under the
# crates.io 10 MiB limit while eliminating tiny one-item crates.
tab=$(printf '\t')
sort -t "$tab" -k1,1nr "$items" |
    while IFS="$tab" read -r item_size category suffix; do
        best_base=
        best_size=-1
        for size_file in "$bins_dir/$category"-*.size; do
            if [ ! -f "$size_file" ]; then continue; fi
            bin_base=${size_file%.size}
            bin_size=$(cat "$size_file")
            combined=$((bin_size + item_size))
            if [ "$combined" -le "$partition_limit" ] && [ "$bin_size" -gt "$best_size" ]; then
                best_base=$bin_base
                best_size=$bin_size
            fi
        done
        if [ -z "$best_base" ]; then
            index=1
            while :; do
                best_base="$bins_dir/$category-$(printf '%03d' "$index")"
                if [ ! -e "$best_base.paths" ]; then break; fi
                index=$((index + 1))
            done
            : > "$best_base.paths"
            best_size=0
        fi
        cat "$items_dir/$category-$suffix.paths" >> "$best_base.paths"
        printf '%s\n' "$((best_size + item_size))" > "$best_base.size"
    done

for paths in "$bins_dir"/*.paths; do
    if [ ! -f "$paths" ]; then continue; fi
    suffix=${paths##*/}
    suffix=${suffix%.paths}
    set --
    while IFS= read -r relative; do
        set -- "$@" "$relative"
    done < "$paths"
    write_partition "$suffix" "$@"
done

printf '%s\n' '];' >> "$root/shader-slang-src/src/sources.rs"
while IFS= read -r crate_name; do
    cat >> "$root/shader-slang-src/Cargo.toml" <<EOF
$crate_name = { path = "../$crate_name", version = "=$version" }
EOF
done < "$components"

# Package each partition to measure exactly what crates.io will receive.
# Remove packages from earlier layouts so target/package matches this source set.
mkdir -p "$root/target/package"
find "$root/target/package" -maxdepth 1 -type f -name 'shader-slang-src-*.crate' \
    -exec rm -f {} +
while IFS= read -r crate_name; do
    cargo package --quiet --allow-dirty --no-verify \
        --manifest-path "$root/$crate_name/Cargo.toml"
    package="$root/target/package/$crate_name-$version.crate"
    package_size=$(wc -c < "$package")
    package_size=$(printf '%s' "$package_size" | tr -d '[:space:]')
    if [ "$package_size" -gt 10485760 ]; then
        echo "$crate_name is $package_size bytes; crates.io allows at most 10485760" >&2
        exit 1
    fi
    printf '%-64s %10s bytes\n' "$crate_name" "$package_size"
done < "$components"

printf 'Packaged shader-slang %s as crate version %s (%s partitions).\n' \
    "$release" "$version" "$(wc -l < "$components" | tr -d '[:space:]')"
